# Packs Ivan's eight perk machines (AI-generated by him, Hunyuan3D-2 style: one textured GLB each, the texture embedded) into the
# PRP1 binary meshes that Core/PropModels.LoadRaw reads, plus a JPEG albedo per machine.
#   python tools/perks/pack_perk_machines.py <folder with the eight .glb files>
# glTF is right-handed Y-up; Unity is left-handed, so x is negated and the winding flipped. Each machine is turned so
# its front faces +z, scaled to stand HEIGHT tall (smaller if it would be too wide or deep for its wall spot), and its
# origin put at the middle of the base's back edge. The back edge ignores the few vertices of anything sticking out
# behind (a crank, a pipe): they sink into the wall instead of pushing the machine into the room.
import sys, os, glob, struct, numpy as np, trimesh
HEIGHT, MAX_WIDTH, MAX_DEPTH = 2.05, 1.6, 1.45
# File (uuid prefix) -> (PerkKind slug, quarter turns so the front faces +z). The order is PerkData's.
MACHINES = {
    'dc8e53a5': ('ironhide', 0),       # navy and brass, gauges and gears: armour-plated
    '6fd96b50': ('slick_fingers', 0),  # rack of coloured cartridges under a candy dome
    '280d5cf0': ('second_wind', 0),    # white and red with a bell: a medic's station
    '24b84935': ('hair_trigger', 0),   # amber arcade cabinet
    '5f78d32a': ('fleet_foot', -1),    # big wheels on the sides; front was its -x side
    'd13d2cc8': ('steady_hand', 0),    # white and violet, a precise little dispenser
    '636a099f': ('hazard_ward', 0),    # diving-helmet porthole: a sealed hazard suit
    'ca3338ab': ('bloodline', 0),      # heart-shaped badge on the screen
}
src = sys.argv[1]
out = os.path.join(os.path.dirname(__file__), '..', '..', 'Assets', '_Project', 'Resources', 'CC0', 'Perks')
os.makedirs(out, exist_ok=True)
files = {os.path.basename(f)[:8]: f for f in glob.glob(os.path.join(src, '*'))}
for prefix, (slug, turns) in MACHINES.items():
    key = next(k for k in files if prefix in os.path.basename(files[k]))
    g = list(trimesh.load(files[key], file_type='glb').geometry.values())[0]
    # trimesh already turns glTF's top-left UVs into the bottom-left ones Unity uses.
    P, N, U, F = g.vertices.copy(), g.vertex_normals.copy(), g.visual.uv.copy(), g.faces.copy()
    yaw = turns * np.pi / 2
    c, s = round(np.cos(yaw)), round(np.sin(yaw))
    R = np.array([[c, 0, -s], [0, 1, 0], [s, 0, c]])
    P, N = P @ R.T, N @ R.T
    P[:, 0] *= -1; N[:, 0] *= -1
    F = F[:, [0, 2, 1]]
    lo, hi = P.min(0), P.max(0)
    back = np.percentile(P[:, 2], 2)
    size = np.array([hi[0] - lo[0], hi[1] - lo[1], hi[2] - back])
    k = min(HEIGHT / size[1], MAX_WIDTH / size[0], MAX_DEPTH / size[2])
    P = (P - [(lo[0] + hi[0]) / 2, lo[1], back]) * k
    with open(os.path.join(out, slug + '.bytes'), 'wb') as f:
        name = slug.encode()
        f.write(b'PRP1'); f.write(struct.pack('<i', 1)); f.write(struct.pack('<i', len(name))); f.write(name)
        f.write(struct.pack('<i', len(P)))
        for a in (P, N, U): f.write(a.astype('<f4').tobytes())
        t = F.reshape(-1); f.write(struct.pack('<i', len(t))); f.write(t.astype('<i4').tobytes())
    g.visual.material.baseColorTexture.convert('RGB').save(os.path.join(out, slug + '_albedo.jpg'), quality=88)
    print('%-14s verts %d tris %d size %s' % (slug, len(P), len(F), np.round(size * k, 2)))
